    private void rSButtonRound1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_rSButtonRound1ActionPerformed
        String correoIngresado = txtCorreo.getText().trim();

        if (correoIngresado.isEmpty()) {
            JOptionPane.showMessageDialog(this, "Debe ingresar su correo registrado.", "Campos Vacíos", JOptionPane.WARNING_MESSAGE);
            return;
        }

        RecuperarContrasenaMetodo recuperador = new RecuperarContrasenaMetodo();

        // 1. Inicia el proceso de recuperación (verifica, genera token, envía email)
        if (recuperador.iniciarRecuperacion(correoIngresado)) {
            // 2. Si el correo se envió con éxito, abre el formulario del Paso 2
            Recuperar.removeAll();
            Recuperar.add(Confirmar);
            Recuperar.repaint();
            Recuperar.revalidate();
        }
    }//GEN-LAST:event_rSButtonRound1ActionPerformed

    private void btnVerificarTokenActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnVerificarTokenActionPerformed
        String tokenIngresado = txtToken.getText().trim();

    RecuperarContrasenaMetodo recuperador = new RecuperarContrasenaMetodo();
    
    // Llamamos al nuevo método de verificación
    String correoVerificado = recuperador.verificarToken(tokenIngresado); 
    
    if (correoVerificado != null) {
        // TOKEN VÁLIDO: Pasa al tercer panel
        JOptionPane.showMessageDialog(this, "Código verificado con éxito.", "Éxito", JOptionPane.INFORMATION_MESSAGE);
        
        // Guarda el token (para usarlo en el Paso 3, así sabes qué fila actualizar)
        this.tokenParaRestablecer = tokenIngresado; 
        
        // Transición a NuevaContraseña
        Recuperar.removeAll();
        Recuperar.add(NuevaContraseña); // <-- Panel para la Nueva Contraseña
        Recuperar.repaint();
        Recuperar.revalidate();
        
    } else {
        // TOKEN INVÁLIDO O EXPIRADO
        JOptionPane.showMessageDialog(this, "Código inválido o expirado. Intente de nuevo.", "Error de Verificación", JOptionPane.ERROR_MESSAGE);
        // El usuario se queda en el panel 'Confirmar' para reintentar.
    }
    }//GEN-LAST:event_btnVerificarTokenActionPerformed

    private void btnCambiarPwdActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnCambiarPwdActionPerformed
        String nuevaContrasena = new String(txtNuevaContrasena.getPassword());
    String confirmarContrasena = new String(txtConfirmarContrasena.getPassword());
    
    if (nuevaContrasena.isEmpty() || confirmarContrasena.isEmpty()) {
        JOptionPane.showMessageDialog(this, "Debe ingresar y confirmar la nueva contraseña.", "Campos Vacíos", JOptionPane.WARNING_MESSAGE);
        return;
    }
    
    if (!nuevaContrasena.equals(confirmarContrasena)) {
        JOptionPane.showMessageDialog(this, "Las contraseñas no coinciden. Por favor, revíselas.", "Error", JOptionPane.ERROR_MESSAGE);
        return;
    }
    
    String contrasenaParaGuardar = nuevaContrasena;
    
    RecuperarContrasenaMetodo recuperador = new RecuperarContrasenaMetodo();
    
    if (recuperador.restablecerContrasena(this.tokenParaRestablecer, contrasenaParaGuardar)) {
        
        JOptionPane.showMessageDialog(this, "Contraseña restablecida con éxito. Ya puedes iniciar sesión.", "Éxito", JOptionPane.INFORMATION_MESSAGE);

        this.dispose(); 
        new Sesion().setVisible(true); 
        
    } else {
        JOptionPane.showMessageDialog(this, "Error al actualizar la contraseña.", "Error", JOptionPane.ERROR_MESSAGE);
    }
    }//GEN-LAST:event_btnCambiarPwdActionPerformed

